import mongoose from "mongoose"

const ticketSchema = new mongoose.Schema(
    {
        ticketId: {
            type: String,
            unique: true,
            // Not required in schema - generated by pre-save middleware
        },
        subject: {
            type: String,
            required: [true, "Subject is required"],
            trim: true,
        },
        description: {
            type: String,
            required: [true, "Description is required"],
        },
        status: {
            type: String,
            enum: ["Open", "In Progress", "Pending", "Resolved", "Closed"],
            default: "Open",
        },
        priority: {
            type: String,
            enum: ["Low", "Medium", "High", "Urgent"],
            default: "Medium",
        },
        category: {
            type: String,
            required: [true, "Category is required"],
        },
        creator: {
            type: mongoose.Schema.Types.Mixed,
            required: [true, "Creator is required"],
            validate: {
                validator: function(value) {
                    // Allow ObjectId strings or specific system values
                    return mongoose.Types.ObjectId.isValid(value) || 
                           ['chatbot', 'system', 'api'].includes(value);
                },
                message: 'Creator must be a valid ObjectId or one of: chatbot, system, api'
            }
        },
        requester: {
            email: {
                type: String,
                required: [true, "Requester email is required"],
                trim: true,
            },
            registrationNumber: {
                type: String,
                required: [true, "Requester registration number is required"],
                trim: true,
            },
            name: {
                type: String,
                trim: true,
            },
        },
        assignee: {
            type: mongoose.Schema.Types.ObjectId,
            ref: "User",
            default: null,
        },
        tags: [String],
        attachments: [
            {
                filename: String,
                path: String,
                mimetype: String,
                size: Number,
                uploadedAt: {
                    type: Date,
                    default: Date.now,
                },
            },
        ],
        dueDate: Date,
        responseTime: Number, // Time in minutes to first response
        resolutionTime: Number, // Time in minutes to resolution
        isEscalated: {
            type: Boolean,
            default: false,
        },
        source: {
            type: String,
            enum: ["email", "web", "chat", "phone", "other"],
            default: "web",
        },
        customFields: {
            type: Map,
            of: mongoose.Schema.Types.Mixed,
        },
    },
    {
        timestamps: true,
        toJSON: { virtuals: true },
        toObject: { virtuals: true },
    },
)

// Virtual for messages
ticketSchema.virtual("messages", {
    ref: "Message",
    localField: "_id",
    foreignField: "ticket",
})

// Virtual for notes
ticketSchema.virtual("notes", {
    ref: "Note",
    localField: "_id",
    foreignField: "ticket",
})

// Virtual for history
ticketSchema.virtual("history", {
    ref: "TicketHistory",
    localField: "_id",
    foreignField: "ticket",
})

// Generate ticket ID before saving
ticketSchema.pre("save", async function (next) {
    if (this.isNew && !this.ticketId) {
        try {
            // Generate unique ticket ID
            this.ticketId = await generateUniqueTicketId()
            console.log(`Generated ticket ID: ${this.ticketId}`)
        } catch (error) {
            console.error('Failed to generate ticket ID:', error)
            return next(new Error('Failed to generate ticket ID'))
        }
    }
    next()
})

// Helper function to generate unique ticket ID with retry logic
async function generateUniqueTicketId(retries = 5) {
    for (let i = 0; i < retries; i++) {
        try {
            // Get current timestamp to ensure uniqueness
            const now = new Date()
            const year = now.getFullYear().toString().slice(-2)
            const month = (now.getMonth() + 1).toString().padStart(2, '0')
            const day = now.getDate().toString().padStart(2, '0')
            
            // Get count and add random factor to prevent collisions
            const count = await mongoose.model("Ticket").countDocuments()
            const randomSuffix = Math.floor(Math.random() * 100).toString().padStart(2, '0')
            const sequentialNumber = (count + 1 + i).toString().padStart(4, '0')
            
            const ticketId = `TKT-${year}${month}${day}-${sequentialNumber}`
            
            // Check if this ID already exists
            const existing = await mongoose.model("Ticket").findOne({ ticketId })
            if (!existing) {
                return ticketId
            }
        } catch (error) {
            console.error(`Error generating ticket ID (attempt ${i + 1}):`, error)
        }
    }
    
    // Fallback: use timestamp-based ID
    const timestamp = Date.now().toString().slice(-8)
    return `TKT-${timestamp}`
}

// Add ticket history on status change
ticketSchema.pre("save", async function (next) {
    if (this.isModified("status") || this.isModified("priority") || this.isModified("assignee")) {
        const TicketHistory = mongoose.model("TicketHistory")

        let action = ""
        if (this.isModified("status")) {
            action = `Status changed to ${this.status}`
        } else if (this.isModified("priority")) {
            action = `Priority changed to ${this.priority}`
        } else if (this.isModified("assignee")) {
            if (this.assignee) {
                const User = mongoose.model("User")
                const assignee = await User.findById(this.assignee)
                action = `Assigned to ${assignee.fullName}`
            } else {
                action = "Unassigned"
            }
        }

        await TicketHistory.create({
            ticket: this._id,
            action,
            actor: this._modifiedBy || null, // This would be set by the controller
        })
    }

    next()
})

const Ticket = mongoose.model("Ticket", ticketSchema)

export default Ticket
